// Packs the two icon sets the category picker offers (IconPicker.tsx) into
// one file each, fetched by the UI only when it needs them:
//   public/tabler-icons.json  Tabler's outline icons (@tabler/icons, MIT) --
//                             line drawings on a 24x24 stroke canvas;
//   public/fluent-icons.json  Microsoft's Fluent Emoji, flat style
//                             (@iconify-json/fluent-emoji-flat, MIT) --
//                             coloured, 32x32, skin-tone variants left out.
// Both are a list of [name, category, "tag tag ...", "<inner svg>"].
// Generated by `npm run build` (and `npm run icons`); git-ignored.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
// The packages' exports maps hide their own files from require.resolve.
const pkgDir = (name) => resolve(here, "../node_modules", name);
const readJson = (path) => JSON.parse(readFileSync(path, "utf8"));
const write = (file, data, what) => {
  writeFileSync(resolve(here, "../public", file), JSON.stringify(data));
  console.log(`${file}: ${data.icons.length} ${what}`);
};

// ── Tabler ────────────────────────────────────────────────────────────────
{
  const pkg = pkgDir("@tabler/icons");
  const meta = readJson(resolve(pkg, "icons.json"));
  const nodes = readJson(resolve(pkg, "tabler-nodes-outline.json"));
  const { version } = readJson(resolve(pkg, "package.json"));
  const esc = (v) => String(v).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  const icons = Object.entries(nodes).map(([name, parts]) => [
    name,
    meta[name]?.category ?? "",
    (meta[name]?.tags ?? []).join(" "),
    parts.map(([tag, attrs]) =>
      `<${tag}${Object.entries(attrs).map(([k, v]) => ` ${k}="${esc(v)}"`).join("")}/>`).join(""),
  ]);
  write("tabler-icons.json", { version, icons }, `Tabler icons (${version})`);
}

// ── Fluent Emoji (flat) ───────────────────────────────────────────────────
{
  const pkg = pkgDir("@iconify-json/fluent-emoji-flat");
  const { icons: all } = readJson(resolve(pkg, "icons.json"));
  const { categories } = readJson(resolve(pkg, "metadata.json"));
  const { version } = readJson(resolve(pkg, "package.json"));
  const categoryOf = {};
  for (const [cat, names] of Object.entries(categories)) for (const n of names) categoryOf[n] = cat;
  const tone = /-(light|medium-light|medium|medium-dark|dark)(-|$)/;
  const icons = Object.entries(all)
    .filter(([name]) => !tone.test(name))
    .map(([name, { body }]) => [name, categoryOf[name] ?? "", "", body]);
  write("fluent-icons.json", { version, icons }, `Fluent Emoji (${version})`);
}
